clear;
clc;
close all;

%% Step 1: Define x-values

x = -20:0.5:20;

%% Step 2: Define two brightness models

% Model form: B(x) = -k(x - h)^2 + Bmax

% Streetlight 1
k1 = 0.08;
h1 = -5;
Bmax1 = 100;

B1 = -k1 .* (x - h1).^2 + Bmax1;

% Streetlight 2
k2 = 0.06;
h2 = 7;
Bmax2 = 90;

B2 = -k2 .* (x - h2).^2 + Bmax2;

%% Step 3: Plot both models

figure; %[output:1913bfc9]
plot(x, B1, 'LineWidth', 2); %[output:1913bfc9]
hold on; %[output:1913bfc9]
plot(x, B2, 'LineWidth', 2); %[output:1913bfc9]
grid on; %[output:1913bfc9]

xlabel('Position Along Road, x'); %[output:1913bfc9]
ylabel('Brightness'); %[output:1913bfc9]
title('Streetlight Brightness Models'); %[output:1913bfc9]

legend('Streetlight 1', 'Streetlight 2'); %[output:1913bfc9]

%% Step 4: Find maximum brightness for each model

[maxBrightness1, index1] = max(B1);
xMax1 = x(index1);

[maxBrightness2, index2] = max(B2);
xMax2 = x(index2);

%% Step 5: Find approximate intersection

difference = abs(B1 - B2);
[minDifference, intersectionIndex] = min(difference);

xIntersection = x(intersectionIndex);
brightnessIntersection = B1(intersectionIndex);

%% Display results

disp("Streetlight 1 maximum brightness:"); %[output:0047c8ba]
disp(maxBrightness1); %[output:4bf94bf1]

disp("Streetlight 1 maximum location:"); %[output:923a43fd]
disp(xMax1); %[output:4bf07973]

disp("Streetlight 2 maximum brightness:"); %[output:05e72806]
disp(maxBrightness2); %[output:6d4a20c4]

disp("Streetlight 2 maximum location:"); %[output:62206b8d]
disp(xMax2); %[output:7cbda7e1]

disp("Approximate intersection location:"); %[output:0dba7f11]
disp(xIntersection); %[output:2159fce6]

disp("Approximate equal brightness value:"); %[output:1b8981ab]
disp(brightnessIntersection); %[output:40945517]

%% Interpretation

disp("Interpretation:"); %[output:4927721f]
disp("Each brightness curve is maximized at its vertex location h."); %[output:0786adef]
disp("Streetlight 1 peaks at x = -5 with brightness 100."); %[output:446ed2e5]
disp("Streetlight 2 peaks at x = 7 with brightness 90."); %[output:4484ff2e]
disp("The intersection is where both streetlights have about the same brightness."); %[output:5ee81761]

